const utils = global.get("utils");
const clients = msg.payload;
if (!clients || Object.keys(clients).length === 0) {
    node.error("Missing client configurations");
    return [null, null];
}
// Build stable key and check if this connection already exists
const name = utils.build_connection_name(Object.values(clients));
const connections = global.get("parat_bridge.connections") || {};
msg.clients = clients;
msg.connection_name = name;
// Output 1 → update connection, Output 2 → create new connection
if (connections[name]) {
    return [msg, null];
} else {
    return [null, msg];
}

const name = msg.connection_name;
const connection = global.get("parat_bridge.connections")[name];

// Refresh clients — preserve existing timestamps
Object.values(msg.clients).forEach(client => {
    const existing = connection.clients && connection.clients[client.identifier];
    client.timestamp = (existing && existing.timestamp && !isNaN(existing.timestamp))
        ? existing.timestamp
        : Date.now();
});
connection.clients = msg.clients;
connection.active = true;

// Ensure required fields exist on legacy connections
connection.failed_entries = connection.failed_entries || {};
if (Array.isArray(connection.failed_entries)) connection.failed_entries = {};
connection.status = connection.status || {};
connection.status.failed_clients = connection.status.failed_clients || [];

// Retry previously failed entries
const hasFailedEntries = Object.values(connection.failed_entries).some(arr => arr.length > 0);
if (hasFailedEntries) {
    connection.retry_failed = true;
}

global.set(`parat_bridge.connections.${name}`, connection);
node.log("Updated existing connection: " + name);
msg.payload = connection;
return msg;

const name = msg.connection_name;
const clients = msg.clients;

// Set initial timestamp on each client
Object.values(clients).forEach(client => {
    client.timestamp = Date.now();
});

const connection = {
    name: name,
    time_created: Date.now(),
    clients: clients,
    active: true,
    master_log: [],
    failed_entries: {},
    status: {
        failed_clients: []
    },
    retry_failed: false
};

const connections = global.get("parat_bridge.connections") || {};
connections[name] = connection;
global.set("parat_bridge.connections", connections);
node.log("Created new connection: " + name);

msg.payload = connection;
return msg;
